INSERT INTO fee_standard_items (id, library_id, section_id, item_no, name, kind, content, sort_order, created_at) VALUES (gen_random_uuid(), 'f13aed01-cb3e-506a-bdd7-ee7fc5e5db7a', '57a6014b-9132-5d69-84ef-346f34861dbf', NULL, '一、辽宁省建设工程计价依据《建设工程费用标准》（以下简称本费用标准）是国有投资或', 'ITEM', '一、辽宁省建设工程计价依据《建设工程费用标准》（以下简称本费用标准）是国有投资或国有投资为主的建设项目，编制工程量清单、招标控制价、施工图预算、工程竣工结算的依据；是评定投标报价合理性的依据；是调解处理工程造价争议和纠纷、审计和司法鉴定的依据；是编制投资估算指标、概算指标和概算定额的依据。非国有资金投资的建设工程可参照本定额相关规定执行。', 1, now());
INSERT INTO fee_standard_items (id, library_id, section_id, item_no, name, kind, content, sort_order, created_at) VALUES (gen_random_uuid(), 'f13aed01-cb3e-506a-bdd7-ee7fc5e5db7a', '57a6014b-9132-5d69-84ef-346f34861dbf', NULL, '二、本费用标准与2024 年辽宁省《房屋建筑与装饰工程定额》、《装配式建筑工程定', 'ITEM', '二、本费用标准与2024 年辽宁省《房屋建筑与装饰工程定额》、《装配式建筑工程定额》、《绿色建筑工程定额》、《通用安装工程定额》、《市政工程定额》配套使用。', 2, now());
INSERT INTO fee_standard_items (id, library_id, section_id, item_no, name, kind, content, sort_order, created_at) VALUES (gen_random_uuid(), 'f13aed01-cb3e-506a-bdd7-ee7fc5e5db7a', '57a6014b-9132-5d69-84ef-346f34861dbf', NULL, '三、2024 年辽宁省建设工程计价依据各专业工程定额的综合单价包括人工费、材料费', 'ITEM', '三、2024 年辽宁省建设工程计价依据各专业工程定额的综合单价包括人工费、材料费、机械费和综合费用，其中综合费用包括本费用标准中的企业管理费和利润。', 3, now());
INSERT INTO fee_standard_items (id, library_id, section_id, item_no, name, kind, content, sort_order, created_at) VALUES (gen_random_uuid(), 'f13aed01-cb3e-506a-bdd7-ee7fc5e5db7a', '57a6014b-9132-5d69-84ef-346f34861dbf', NULL, '四、本费用标准中的各项费用均不包含增值税可抵扣进项税额。', 'ITEM', '四、本费用标准中的各项费用均不包含增值税可抵扣进项税额。', 4, now());
INSERT INTO fee_standard_items (id, library_id, section_id, item_no, name, kind, content, sort_order, created_at) VALUES (gen_random_uuid(), 'f13aed01-cb3e-506a-bdd7-ee7fc5e5db7a', '57a6014b-9132-5d69-84ef-346f34861dbf', NULL, '五、本费用标准中的企业管理费、利润、文明施工和环境保护费、雨季施工费、冬季施工费', 'ITEM', '五、本费用标准中的企业管理费、利润、文明施工和环境保护费、雨季施工费、冬季施工费、市政工程施工干扰费均为社会平均水平的基础费率。投标人在投标报价或非招标工程在签订施工合同时，应考虑工程复杂程度、工程规模、工期要求、风险等因素确定费率。若合同中没有约定或约定不明确时，视为按本费用标准的基础费率执行。本费用标准中的企业管理费不包含检验试验费，依据《建设工程质量检测管理办法》（第57 号部令）规定，应由建设方委托检测机构开展。', 5, now());
INSERT INTO fee_standard_items (id, library_id, section_id, item_no, name, kind, content, sort_order, created_at) VALUES (gen_random_uuid(), 'f13aed01-cb3e-506a-bdd7-ee7fc5e5db7a', '57a6014b-9132-5d69-84ef-346f34861dbf', NULL, '六、本费用标准中的安全施工费、规费为最低费率，投标人在投标报价时，或非招标工程签', 'ITEM', '六、本费用标准中的安全施工费、规费为最低费率，投标人在投标报价时，或非招标工程签订施工合同时，可根据工程实际和企业自身情况进行上浮，但规费不得高于国家及当地人社部门的相关规定。', 6, now());
INSERT INTO fee_standard_items (id, library_id, section_id, item_no, name, kind, content, sort_order, created_at) VALUES (gen_random_uuid(), 'f13aed01-cb3e-506a-bdd7-ee7fc5e5db7a', '57a6014b-9132-5d69-84ef-346f34861dbf', NULL, '七、智慧工地费用分为智慧工地（安全施工部分）和智慧工地（文明施工和环境保护部分）', 'ITEM', '七、智慧工地费用分为智慧工地（安全施工部分）和智慧工地（文明施工和环境保护部分）,分别包含在安全施工费和文明施工和环境保护费中。', 7, now());
INSERT INTO fee_standard_items (id, library_id, section_id, item_no, name, kind, content, sort_order, created_at) VALUES (gen_random_uuid(), 'f13aed01-cb3e-506a-bdd7-ee7fc5e5db7a', '57a6014b-9132-5d69-84ef-346f34861dbf', NULL, '八、在编制招标控制价时，按本费用标准中的招标控制价编制规定执行，但费率不得低于本', 'ITEM', '八、在编制招标控制价时，按本费用标准中的招标控制价编制规定执行，但费率不得低于本费用标准基础费率及最低费率。', 8, now());
INSERT INTO fee_standard_items (id, library_id, section_id, item_no, name, kind, content, sort_order, created_at) VALUES (gen_random_uuid(), 'f13aed01-cb3e-506a-bdd7-ee7fc5e5db7a', '57a6014b-9132-5d69-84ef-346f34861dbf', NULL, '九、本费用标准不分企业级别与承包方式，均按本费用标准的相关规定计取相应费用。', 'ITEM', '九、本费用标准不分企业级别与承包方式，均按本费用标准的相关规定计取相应费用。', 9, now());
INSERT INTO fee_standard_items (id, library_id, section_id, item_no, name, kind, content, sort_order, created_at) VALUES (gen_random_uuid(), 'f13aed01-cb3e-506a-bdd7-ee7fc5e5db7a', '57a6014b-9132-5d69-84ef-346f34861dbf', NULL, '十、工程量清单计价中的综合单价，是按本费用标准的“工程费用取费程序表”中的企业管', 'ITEM', '十、工程量清单计价中的综合单价，是按本费用标准的“工程费用取费程序表”中的企业管理费和利润计算方法并考虑风险组成的。', 10, now());
INSERT INTO fee_standard_items (id, library_id, section_id, item_no, name, kind, content, sort_order, created_at) VALUES (gen_random_uuid(), 'f13aed01-cb3e-506a-bdd7-ee7fc5e5db7a', '57a6014b-9132-5d69-84ef-346f34861dbf', NULL, '十一、本费用标准中的“×××以上”，不包括×××本身;“×××以下”，包括×××', 'ITEM', '十一、本费用标准中的“×××以上”，不包括×××本身;“×××以下”，包括×××本身。', 11, now());
INSERT INTO fee_standard_items (id, library_id, section_id, item_no, name, kind, content, sort_order, created_at) VALUES (gen_random_uuid(), 'f13aed01-cb3e-506a-bdd7-ee7fc5e5db7a', '1597ad39-8ca2-58d9-bd71-d8107d850eda', NULL, '建设工程费用组成根据住房和城乡建设部、财政部《关于印发<建筑安装工程费用项目组成', 'ITEM', '建设工程费用组成根据住房和城乡建设部、财政部《关于印发<建筑安装工程费用项目组成>的通知》（建标〔2013〕44 号）、住建部《关于做好建筑业营改增建设工程计价依据调整准备工作的通知》（建办标〔2016〕4 号）、财政部和国家税务总局《关于全面推开营业税改征增值税试点的通知》（财税〔2016〕36 号）、财政部、应急部发布了《关于印发＜企业安全生产费用提取和使用管理办法＞的通知》（财资〔2022〕136 号）、《建设工程质量检测管理办法》（第57 号部令），结合我省实际情况，确定建设工程费用项目组成如下：', 12, now());
INSERT INTO fee_standard_items (id, library_id, section_id, item_no, name, kind, content, sort_order, created_at) VALUES (gen_random_uuid(), 'f13aed01-cb3e-506a-bdd7-ee7fc5e5db7a', '1597ad39-8ca2-58d9-bd71-d8107d850eda', NULL, '一、建设工程费用由分部分项工程费、措施项目费、其他项目费、规费、税金组成。分部分', 'ITEM', '一、建设工程费用由分部分项工程费、措施项目费、其他项目费、规费、税金组成。分部分项工程费、措施项目费、其他项目费包含人工费、材料费、施工机具使用费、企业管理费和利润。各项费用组成均不含可抵扣进项税额。', 13, now());
INSERT INTO fee_standard_items (id, library_id, section_id, item_no, name, kind, content, sort_order, created_at) VALUES (gen_random_uuid(), 'f13aed01-cb3e-506a-bdd7-ee7fc5e5db7a', '1597ad39-8ca2-58d9-bd71-d8107d850eda', NULL, '（一）分部分项工程费：是指各专业工程的分部分项工程应予列支的各项费用。', 'ITEM', '（一）分部分项工程费：是指各专业工程的分部分项工程应予列支的各项费用。', 14, now());
INSERT INTO fee_standard_items (id, library_id, section_id, item_no, name, kind, content, sort_order, created_at) VALUES (gen_random_uuid(), 'f13aed01-cb3e-506a-bdd7-ee7fc5e5db7a', '1597ad39-8ca2-58d9-bd71-d8107d850eda', NULL, '1.专业工程：是指按现行国家计量规范划分的房屋建筑与装饰工程、通用安装工程、市政', 'ITEM', '1.专业工程：是指按现行国家计量规范划分的房屋建筑与装饰工程、通用安装工程、市政工程等各类工程。', 15, now());
INSERT INTO fee_standard_items (id, library_id, section_id, item_no, name, kind, content, sort_order, created_at) VALUES (gen_random_uuid(), 'f13aed01-cb3e-506a-bdd7-ee7fc5e5db7a', '1597ad39-8ca2-58d9-bd71-d8107d850eda', NULL, '2.分部分项工程：指按现行国家计量规范对各专业工程划分的项目。如房屋建筑与装饰工', 'ITEM', '2.分部分项工程：指按现行国家计量规范对各专业工程划分的项目。如房屋建筑与装饰工程划分的土石方工程、地基处理与边坡支护工程、桩基工程、砌筑工程等。', 16, now());
INSERT INTO fee_standard_items (id, library_id, section_id, item_no, name, kind, content, sort_order, created_at) VALUES (gen_random_uuid(), 'f13aed01-cb3e-506a-bdd7-ee7fc5e5db7a', '1597ad39-8ca2-58d9-bd71-d8107d850eda', NULL, '（二）措施项目费：是指为完成建设工程施工，发生于该工程施工前和施工过程中的技术、', 'ITEM', '（二）措施项目费：是指为完成建设工程施工，发生于该工程施工前和施工过程中的技术、生活、安全、环境保护等方面的费用。内容包括：', 17, now());
INSERT INTO fee_standard_items (id, library_id, section_id, item_no, name, kind, content, sort_order, created_at) VALUES (gen_random_uuid(), 'f13aed01-cb3e-506a-bdd7-ee7fc5e5db7a', '1597ad39-8ca2-58d9-bd71-d8107d850eda', NULL, '1.技术措施费：是指工程定额中规定的，在施工过程中耗费的非工程实体可以计量的措施', 'ITEM', '1.技术措施费：是指工程定额中规定的，在施工过程中耗费的非工程实体可以计量的措施项目，计入分部分项工程费。内容包括：（1）大型机械设备进出场及安拆费：是指工程定额中列项的大型机械设备进出场及安拆费；（2）混凝土模板及支架费：是指混凝土施工过程中需要的各种模板、支架等的安、拆、运输、使用摊销费用；（3）脚手架费：是指施工需要的各种脚手架搭、拆、运输、使用摊销费用；（4）垂直运输费；（5）施工排水及井点降水；（6）临时设施费：是指施工企业为进行建设工程施工所必须搭设的生活和生产用的临时建筑物、构筑物和其他临时设施费用。包括地面硬覆盖、临时围挡、大门、临时建筑、临时管线安装等临时设施的搭设、维修、拆除、清理费或摊销费等；（7）其他项目。', 18, now());
INSERT INTO fee_standard_items (id, library_id, section_id, item_no, name, kind, content, sort_order, created_at) VALUES (gen_random_uuid(), 'f13aed01-cb3e-506a-bdd7-ee7fc5e5db7a', '1597ad39-8ca2-58d9-bd71-d8107d850eda', NULL, '2.一般措施项目：是指为完成工程项目施工，发生于该工程施工前和施工过程中的非工程', 'ITEM', '2.一般措施项目：是指为完成工程项目施工，发生于该工程施工前和施工过程中的非工程实体，不可计量，且不包含在工程定额所列的措施项目中的措施项目，一般工程均有发生的。内容包括：（1）安全施工费：是指施工现场安全施工所需要的各项费用。依据《关于印发＜企业安全生产费用提取和使用管理办法＞的通知》（财资〔2022〕136 号），建设工程施工企业安全费用应当按照以下范围使用：①完善、改造和维护安全防护设施设备支出（不含“三同时”要求初期投入的安全设施），包括施工现场临时用电系统、洞口或临边防护、高处作业或交叉作业防护、临时安全防护、支护及防治边坡滑坡、工程有害气体监测和通风、保障安全的机械设备、防火、防爆、防触电、防尘、防毒、防雷、防台风、防地质灾害等设施设备支出；②应急救援技术装备、设施配置及维护保养支出，事故逃生和紧急避难设施设备的配置和应急救援队伍建设、应急预案制修订与应急演练支出；③开展施工现场重大危险源检测、评估、监控支出，安全风险分级管控和事故隐患排查整改支出，工程项目安全生产信息化建设、运维和网络安全支出；④安全生产检查、评估评价（不含新建、改建、扩建项目安全评价）、咨询和标准化建设支出；⑤配备和更新现场作业人员安全防护用品支出；⑥安全生产宣传、教育、培训和从业人员发现并报告事故隐患的奖励支出；⑦安全生产适用的新技术、新标准、新工艺、新装备的推广应用支出；⑧安全设施及特种设备检测检验、检定校准支出；⑨安全生产责任保险支出；⑩与安全生产直接相关的其他支出。其中，智慧工地费用（安全施工费部分）包括：视频安全监控、AI视频安全监控、安全检查记录仪、塔机安全运行监测、吊钩安全可视化、升降机安全运行监测、卸料平台安全监测的安拆和使用费。（2）文明施工和环境保护费：是指施工现场文明施工所需要的各项费用和在施工过程中采取的环境保护措施费用。其中，智慧工地费用（文明施工和环境保护部分）包括：环境监测、喷淋联动、大型车辆冲洗平台、水电监控的安拆和使用费。（3）雨季施工费：是指在雨季施工需增加的临时设施、防滑、排除雨水，人工及施工机械效率降低等费用。', 19, now());
INSERT INTO fee_standard_items (id, library_id, section_id, item_no, name, kind, content, sort_order, created_at) VALUES (gen_random_uuid(), 'f13aed01-cb3e-506a-bdd7-ee7fc5e5db7a', '1597ad39-8ca2-58d9-bd71-d8107d850eda', NULL, '3.其他措施项目：是指为完成工程项目施工，发生于该工程施工前和施工过程中的非工程', 'ITEM', '3.其他措施项目：是指为完成工程项目施工，发生于该工程施工前和施工过程中的非工程实体，不可计量，且不包含在工程定额所列的措施项目中的措施项目，仅特定工程或特殊条件下发生。内容包括：（1）夜间施工增加费：是指因夜间施工所发生的夜班补助费、夜间施工降效、夜间施工照明设备摊销及照明用电等费用。（2）二次搬运费：是指因施工场地条件限制而发生的材料、构配件、半成品等一次运输不能到达堆放地点，必须进行二次或多次搬运所发生的费用。（3）冬季施工费：是指在冬季施工（连续5 天平均气温在5℃以下环境）需增加的临时设施（不包含暖棚法施工所采用的措施）、防滑、除雪，人工及施工机械效率降低以及水砂石加热、混凝土保温覆盖发生的费用。（4）已完工程及设备保护费：是指竣工验收前，对已完工程及设备采取的必要保护措施所发生的费用。（5）市政工程施工干扰费：市政工程施工中发生的边施工边维护交通及车辆、行人干扰等所发生的防护和保护措施费。', 20, now());
INSERT INTO fee_standard_items (id, library_id, section_id, item_no, name, kind, content, sort_order, created_at) VALUES (gen_random_uuid(), 'f13aed01-cb3e-506a-bdd7-ee7fc5e5db7a', 'a6f787bb-b078-517b-9409-9066e089c860', NULL, '1.暂列金额：是指建设单位在工程量清单中暂定并包括在工程合同价款中的一笔款项。用', 'ITEM', '1.暂列金额：是指建设单位在工程量清单中暂定并包括在工程合同价款中的一笔款项。用于施工合同签订时尚未确定或者不可预见的所需材料、工程设备、服务的采购，施工中可能发生的工程变更、合同约定调整因素出现时的工程价款调整以及发生的索赔、现场签证确认等的费用。', 21, now());
INSERT INTO fee_standard_items (id, library_id, section_id, item_no, name, kind, content, sort_order, created_at) VALUES (gen_random_uuid(), 'f13aed01-cb3e-506a-bdd7-ee7fc5e5db7a', 'a6f787bb-b078-517b-9409-9066e089c860', NULL, '2.计日工：是指在施工过程中，施工企业完成建设单位提出的施工图纸以外的零星项目或', 'ITEM', '2.计日工：是指在施工过程中，施工企业完成建设单位提出的施工图纸以外的零星项目或工作所需的费用。', 22, now());
INSERT INTO fee_standard_items (id, library_id, section_id, item_no, name, kind, content, sort_order, created_at) VALUES (gen_random_uuid(), 'f13aed01-cb3e-506a-bdd7-ee7fc5e5db7a', 'a6f787bb-b078-517b-9409-9066e089c860', NULL, '3.总承包服务费：是指总承包人为配合、协调建设单位进行的专业工程发包，对建设单位', 'ITEM', '3.总承包服务费：是指总承包人为配合、协调建设单位进行的专业工程发包，对建设单位自行采购的材料、工程设备等进行保管以及施工现场管理、竣工资料汇总整理等服务所需的费用。', 23, now());
INSERT INTO fee_standard_items (id, library_id, section_id, item_no, name, kind, content, sort_order, created_at) VALUES (gen_random_uuid(), 'f13aed01-cb3e-506a-bdd7-ee7fc5e5db7a', 'a6f787bb-b078-517b-9409-9066e089c860', NULL, '4.其他未列项目，如暂估价等。', 'ITEM', '4.其他未列项目，如暂估价等。', 24, now());
