INSERT INTO fee_standard_items (id, library_id, section_id, item_no, name, kind, content, sort_order, created_at) VALUES (gen_random_uuid(), 'f13aed01-cb3e-506a-bdd7-ee7fc5e5db7a', '595a6645-a049-576c-9b30-5f54815f4c54', NULL, '（1）养老保险费：是指企业按照规定标准为职工缴纳的基本养老保险费。（2）失业保险', 'ITEM', '（1）养老保险费：是指企业按照规定标准为职工缴纳的基本养老保险费。（2）失业保险费：是指企业按照规定标准为职工缴纳的失业保险费。（3）医疗保险费：是指企业按照规定标准为职工缴纳的基本医疗保险费。（4）生育保险费：是指企业按照规定标准为职工缴纳的生育保险费。（5）工伤保险费：是指企业按照规定标准为职工缴纳的工伤保险费。', 26, now());
INSERT INTO fee_standard_items (id, library_id, section_id, item_no, name, kind, content, sort_order, created_at) VALUES (gen_random_uuid(), 'f13aed01-cb3e-506a-bdd7-ee7fc5e5db7a', '595a6645-a049-576c-9b30-5f54815f4c54', NULL, '2.住房公积金：是指企业按规定标准为职工缴纳的住房公积金。', 'ITEM', '2.住房公积金：是指企业按规定标准为职工缴纳的住房公积金。', 27, now());
INSERT INTO fee_standard_items (id, library_id, section_id, item_no, name, kind, content, sort_order, created_at) VALUES (gen_random_uuid(), 'f13aed01-cb3e-506a-bdd7-ee7fc5e5db7a', '595a6645-a049-576c-9b30-5f54815f4c54', NULL, '3.其他应列而未列入的费用，按实际发生计取。', 'ITEM', '3.其他应列而未列入的费用，按实际发生计取。', 28, now());
INSERT INTO fee_standard_items (id, library_id, section_id, item_no, name, kind, content, sort_order, created_at) VALUES (gen_random_uuid(), 'f13aed01-cb3e-506a-bdd7-ee7fc5e5db7a', '5a227f7a-ea11-5d3e-8d1d-74d95ad22ec6', NULL, '是指国家税法规定的应计入建筑安装工程造价内的增值税销项税额。', 'ITEM', '是指国家税法规定的应计入建筑安装工程造价内的增值税销项税额。', 29, now());
INSERT INTO fee_standard_items (id, library_id, section_id, item_no, name, kind, content, sort_order, created_at) VALUES (gen_random_uuid(), 'f13aed01-cb3e-506a-bdd7-ee7fc5e5db7a', '5a227f7a-ea11-5d3e-8d1d-74d95ad22ec6', NULL, '二、建设工程费用中分部分项工程费、措施项目费、其他项目费包括：', 'ITEM', '二、建设工程费用中分部分项工程费、措施项目费、其他项目费包括：', 30, now());
INSERT INTO fee_standard_items (id, library_id, section_id, item_no, name, kind, content, sort_order, created_at) VALUES (gen_random_uuid(), 'f13aed01-cb3e-506a-bdd7-ee7fc5e5db7a', '5a227f7a-ea11-5d3e-8d1d-74d95ad22ec6', NULL, '（一）人工费：是指按工资总额构成规定，支付给从事建筑安装工程施工的生产工人和附属', 'ITEM', '（一）人工费：是指按工资总额构成规定，支付给从事建筑安装工程施工的生产工人和附属生产单位工人的各项费用。内容包括：', 31, now());
INSERT INTO fee_standard_items (id, library_id, section_id, item_no, name, kind, content, sort_order, created_at) VALUES (gen_random_uuid(), 'f13aed01-cb3e-506a-bdd7-ee7fc5e5db7a', '5a227f7a-ea11-5d3e-8d1d-74d95ad22ec6', NULL, '1.计时工资或计件工资：是指按计时工资标准和工作时间或对已做工作按计件单价支付给', 'ITEM', '1.计时工资或计件工资：是指按计时工资标准和工作时间或对已做工作按计件单价支付给个人的劳动报酬。', 32, now());
INSERT INTO fee_standard_items (id, library_id, section_id, item_no, name, kind, content, sort_order, created_at) VALUES (gen_random_uuid(), 'f13aed01-cb3e-506a-bdd7-ee7fc5e5db7a', '5a227f7a-ea11-5d3e-8d1d-74d95ad22ec6', NULL, '2.奖金：是指对超额劳动和增收节支支付给个人的劳动报酬。如节约奖、劳动竞赛奖等。', 'ITEM', '2.奖金：是指对超额劳动和增收节支支付给个人的劳动报酬。如节约奖、劳动竞赛奖等。', 33, now());
INSERT INTO fee_standard_items (id, library_id, section_id, item_no, name, kind, content, sort_order, created_at) VALUES (gen_random_uuid(), 'f13aed01-cb3e-506a-bdd7-ee7fc5e5db7a', '5a227f7a-ea11-5d3e-8d1d-74d95ad22ec6', NULL, '3.津贴补贴：是指为了补偿职工特殊或额外的劳动消耗和因其他特殊原因支付给个人的津', 'ITEM', '3.津贴补贴：是指为了补偿职工特殊或额外的劳动消耗和因其他特殊原因支付给个人的津贴，以及为了保证职工工资水平不受物价影响支付给个人的物价补贴。如流动施工津贴、特殊地区施工津贴、高温（寒）作业临时津贴、高空津贴等。', 34, now());
INSERT INTO fee_standard_items (id, library_id, section_id, item_no, name, kind, content, sort_order, created_at) VALUES (gen_random_uuid(), 'f13aed01-cb3e-506a-bdd7-ee7fc5e5db7a', '5a227f7a-ea11-5d3e-8d1d-74d95ad22ec6', NULL, '4.加班加点工资：是指按规定支付的在法定节假日工作的加班工资和在法定日工作时间外', 'ITEM', '4.加班加点工资：是指按规定支付的在法定节假日工作的加班工资和在法定日工作时间外延时工作的加点工资。', 35, now());
INSERT INTO fee_standard_items (id, library_id, section_id, item_no, name, kind, content, sort_order, created_at) VALUES (gen_random_uuid(), 'f13aed01-cb3e-506a-bdd7-ee7fc5e5db7a', '5a227f7a-ea11-5d3e-8d1d-74d95ad22ec6', NULL, '5.特殊情况下支付的工资：是指根据国家法律、法规和政策规定，因病、工伤、产假、计', 'ITEM', '5.特殊情况下支付的工资：是指根据国家法律、法规和政策规定，因病、工伤、产假、计划生育假、婚丧假、事假、探亲假、定期休假、停工学习、执行国家或社会义务等原因按计时工资标准或计时工资标准的一定比例支付的工资。', 36, now());
INSERT INTO fee_standard_items (id, library_id, section_id, item_no, name, kind, content, sort_order, created_at) VALUES (gen_random_uuid(), 'f13aed01-cb3e-506a-bdd7-ee7fc5e5db7a', '5a227f7a-ea11-5d3e-8d1d-74d95ad22ec6', NULL, '（二）材料费：是指施工过程中耗费的原材料、辅助材料、构配件、零件、半成品或成品、', 'ITEM', '（二）材料费：是指施工过程中耗费的原材料、辅助材料、构配件、零件、半成品或成品、工程设备的费用，内容包括：', 37, now());
INSERT INTO fee_standard_items (id, library_id, section_id, item_no, name, kind, content, sort_order, created_at) VALUES (gen_random_uuid(), 'f13aed01-cb3e-506a-bdd7-ee7fc5e5db7a', '5a227f7a-ea11-5d3e-8d1d-74d95ad22ec6', NULL, '1.材料原价：是指材料、工程设备的出厂价格或商家供应价格，不包含增值税可抵扣进项', 'ITEM', '1.材料原价：是指材料、工程设备的出厂价格或商家供应价格，不包含增值税可抵扣进项税额。', 38, now());
INSERT INTO fee_standard_items (id, library_id, section_id, item_no, name, kind, content, sort_order, created_at) VALUES (gen_random_uuid(), 'f13aed01-cb3e-506a-bdd7-ee7fc5e5db7a', '5a227f7a-ea11-5d3e-8d1d-74d95ad22ec6', NULL, '2.运杂费：是指材料、工程设备自来源地运至工地仓库或指定堆放地点所发生的全部费用', 'ITEM', '2.运杂费：是指材料、工程设备自来源地运至工地仓库或指定堆放地点所发生的全部费用。', 39, now());
INSERT INTO fee_standard_items (id, library_id, section_id, item_no, name, kind, content, sort_order, created_at) VALUES (gen_random_uuid(), 'f13aed01-cb3e-506a-bdd7-ee7fc5e5db7a', '5a227f7a-ea11-5d3e-8d1d-74d95ad22ec6', NULL, '3.运输损耗费：是指材料在运输装卸过程中不可避免的损耗。', 'ITEM', '3.运输损耗费：是指材料在运输装卸过程中不可避免的损耗。', 40, now());
INSERT INTO fee_standard_items (id, library_id, section_id, item_no, name, kind, content, sort_order, created_at) VALUES (gen_random_uuid(), 'f13aed01-cb3e-506a-bdd7-ee7fc5e5db7a', '5a227f7a-ea11-5d3e-8d1d-74d95ad22ec6', NULL, '4.采购及保管费：是指为组织采购、供应和保管材料、工程设备的过程中所需要的各项费', 'ITEM', '4.采购及保管费：是指为组织采购、供应和保管材料、工程设备的过程中所需要的各项费用。包括采购费、仓储费、工地保管费、仓储损耗。工程设备是指构成或计划构成永久工程一部分的机电设备、金属结构设备、仪器装置及其他类似的设备和装置。', 41, now());
INSERT INTO fee_standard_items (id, library_id, section_id, item_no, name, kind, content, sort_order, created_at) VALUES (gen_random_uuid(), 'f13aed01-cb3e-506a-bdd7-ee7fc5e5db7a', '5a227f7a-ea11-5d3e-8d1d-74d95ad22ec6', NULL, '（三）施工机具使用费：是指施工作业所发生的施工机械、仪器仪表使用费。', 'ITEM', '（三）施工机具使用费：是指施工作业所发生的施工机械、仪器仪表使用费。', 42, now());
INSERT INTO fee_standard_items (id, library_id, section_id, item_no, name, kind, content, sort_order, created_at) VALUES (gen_random_uuid(), 'f13aed01-cb3e-506a-bdd7-ee7fc5e5db7a', '5a227f7a-ea11-5d3e-8d1d-74d95ad22ec6', NULL, '1.施工机械使用费：以施工机械台班耗用量乘以施工机械台班单价表示，施工机械台班单', 'ITEM', '1.施工机械使用费：以施工机械台班耗用量乘以施工机械台班单价表示，施工机械台班单价应由下列七项费用组成：（1）折旧费：指施工机械在规定的使用年限内，陆续收回其原值的费用。（2）大修理费：指施工机械按规定的大修理间隔台班进行必要的大修理，以恢复其正常功能所需的费用。（3）经常修理费：指施工机械除大修理以外的各级保养和临时故障排除所需的费用。包括为保障机械正常运转所需替换设备与随机配备工具附具的摊销和维护费用，机械运转中日常保养所需润滑与擦拭的材料费用及机械停滞期间的维护和保养费用等。（4）安拆费及场外运费：安拆费指施工机械（大型机械除外）在现场进行安装与拆卸所需的人工、材料、机械和试运转费用以及机械辅助设施的折旧、搭设、拆除等费用；场外运费指施工机械整体或分体自停放地点运至施工现场或由一施工地点运至另一施工地点的运输、装卸、辅助材料及架线等费用。（5）人工费：指机上司机（司炉）和其他操作人员的人工费。（6）燃料动力费：指施工机械在运转作业中所消耗的各种燃料及水、电等。（7）税费：指施工机械按照国家规定应缴纳的车船使用税、保险费及年检费等。', 43, now());
INSERT INTO fee_standard_items (id, library_id, section_id, item_no, name, kind, content, sort_order, created_at) VALUES (gen_random_uuid(), 'f13aed01-cb3e-506a-bdd7-ee7fc5e5db7a', '5a227f7a-ea11-5d3e-8d1d-74d95ad22ec6', NULL, '2.仪器仪表使用费：是指工程施工所需使用的仪器仪表的摊销及维修费用。', 'ITEM', '2.仪器仪表使用费：是指工程施工所需使用的仪器仪表的摊销及维修费用。', 44, now());
INSERT INTO fee_standard_items (id, library_id, section_id, item_no, name, kind, content, sort_order, created_at) VALUES (gen_random_uuid(), 'f13aed01-cb3e-506a-bdd7-ee7fc5e5db7a', '5a227f7a-ea11-5d3e-8d1d-74d95ad22ec6', NULL, '（四）企业管理费：是指建筑安装企业组织施工生产和经营管理所需的费用。内容包括：', 'ITEM', '（四）企业管理费：是指建筑安装企业组织施工生产和经营管理所需的费用。内容包括：', 45, now());
INSERT INTO fee_standard_items (id, library_id, section_id, item_no, name, kind, content, sort_order, created_at) VALUES (gen_random_uuid(), 'f13aed01-cb3e-506a-bdd7-ee7fc5e5db7a', '5a227f7a-ea11-5d3e-8d1d-74d95ad22ec6', NULL, '1.管理人员工资:是指按规定支付给管理人员的计时工资、奖金、津贴补贴、加班加点工', 'ITEM', '1.管理人员工资:是指按规定支付给管理人员的计时工资、奖金、津贴补贴、加班加点工资及特殊情况下支付的工资等。', 46, now());
INSERT INTO fee_standard_items (id, library_id, section_id, item_no, name, kind, content, sort_order, created_at) VALUES (gen_random_uuid(), 'f13aed01-cb3e-506a-bdd7-ee7fc5e5db7a', '5a227f7a-ea11-5d3e-8d1d-74d95ad22ec6', NULL, '2.办公费：是指企业管理办公用的文具、纸张、帐表、印刷、邮电、书报、办公软件、现', 'ITEM', '2.办公费：是指企业管理办公用的文具、纸张、帐表、印刷、邮电、书报、办公软件、现场监控、会议、水电（包含施工现场生活用水用电）、烧水和集体取暖降温（包括现场临时宿舍取暖降温）等费用。', 47, now());
INSERT INTO fee_standard_items (id, library_id, section_id, item_no, name, kind, content, sort_order, created_at) VALUES (gen_random_uuid(), 'f13aed01-cb3e-506a-bdd7-ee7fc5e5db7a', '5a227f7a-ea11-5d3e-8d1d-74d95ad22ec6', NULL, '3.差旅交通费：是指职工因公出差、调动工作的差旅费、住勤补助费，市内交通费和误餐', 'ITEM', '3.差旅交通费：是指职工因公出差、调动工作的差旅费、住勤补助费，市内交通费和误餐补助费，职工探亲路费，劳动力招募费，职工退休、退职一次性路费，工伤人员就医路费，工地转移费以及管理部门使用的交通工具的油料、燃料等费用。', 48, now());
INSERT INTO fee_standard_items (id, library_id, section_id, item_no, name, kind, content, sort_order, created_at) VALUES (gen_random_uuid(), 'f13aed01-cb3e-506a-bdd7-ee7fc5e5db7a', '5a227f7a-ea11-5d3e-8d1d-74d95ad22ec6', NULL, '4.固定资产使用费：是指管理和试验部门及附属生产单位使用的属于固定资产的房屋、设', 'ITEM', '4.固定资产使用费：是指管理和试验部门及附属生产单位使用的属于固定资产的房屋、设备、仪器等的折旧、大修、维修或租赁费。', 49, now());
INSERT INTO fee_standard_items (id, library_id, section_id, item_no, name, kind, content, sort_order, created_at) VALUES (gen_random_uuid(), 'f13aed01-cb3e-506a-bdd7-ee7fc5e5db7a', '5a227f7a-ea11-5d3e-8d1d-74d95ad22ec6', NULL, '5.工具用具使用费：是指企业施工生产和管理使用的不属于固定资产的工具、器具、家具', 'ITEM', '5.工具用具使用费：是指企业施工生产和管理使用的不属于固定资产的工具、器具、家具、交通工具和检验、试验、测绘、消防用具等的购置、维修和摊销费。', 50, now());
INSERT INTO fee_standard_items (id, library_id, section_id, item_no, name, kind, content, sort_order, created_at) VALUES (gen_random_uuid(), 'f13aed01-cb3e-506a-bdd7-ee7fc5e5db7a', '5a227f7a-ea11-5d3e-8d1d-74d95ad22ec6', NULL, '6.劳动保险和职工福利费：是指由企业支付的职工退职金、按规定支付给离休干部的经费', 'ITEM', '6.劳动保险和职工福利费：是指由企业支付的职工退职金、按规定支付给离休干部的经费，集体福利费、夏季防暑降温、冬季取暖补贴、上下班交通补贴等。', 51, now());
INSERT INTO fee_standard_items (id, library_id, section_id, item_no, name, kind, content, sort_order, created_at) VALUES (gen_random_uuid(), 'f13aed01-cb3e-506a-bdd7-ee7fc5e5db7a', '5a227f7a-ea11-5d3e-8d1d-74d95ad22ec6', NULL, '7.劳动保护费：是企业按规定发放的劳动保护用品的支出。如工作服、手套、防暑降温饮', 'ITEM', '7.劳动保护费：是企业按规定发放的劳动保护用品的支出。如工作服、手套、防暑降温饮料以及在有碍身体健康的环境中施工的保健费用等。', 52, now());
INSERT INTO fee_standard_items (id, library_id, section_id, item_no, name, kind, content, sort_order, created_at) VALUES (gen_random_uuid(), 'f13aed01-cb3e-506a-bdd7-ee7fc5e5db7a', '5a227f7a-ea11-5d3e-8d1d-74d95ad22ec6', NULL, '8.工会经费：是指企业按《工会法》规定的全部职工工资总额比例计提的工会经费。', 'ITEM', '8.工会经费：是指企业按《工会法》规定的全部职工工资总额比例计提的工会经费。', 53, now());
INSERT INTO fee_standard_items (id, library_id, section_id, item_no, name, kind, content, sort_order, created_at) VALUES (gen_random_uuid(), 'f13aed01-cb3e-506a-bdd7-ee7fc5e5db7a', '5a227f7a-ea11-5d3e-8d1d-74d95ad22ec6', NULL, '9.职工教育经费：是指按职工工资总额的规定比例计提，企业为职工进行专业技术和职业', 'ITEM', '9.职工教育经费：是指按职工工资总额的规定比例计提，企业为职工进行专业技术和职业技能培训，专业技术人员继续教育、职工职业技能鉴定、职业资格认定以及根据需要对职工进行各类文化教育所发生的费用。', 54, now());
INSERT INTO fee_standard_items (id, library_id, section_id, item_no, name, kind, content, sort_order, created_at) VALUES (gen_random_uuid(), 'f13aed01-cb3e-506a-bdd7-ee7fc5e5db7a', '5a227f7a-ea11-5d3e-8d1d-74d95ad22ec6', NULL, '10.财产保险费：是指施工管理用财产、车辆等的保险费用。', 'ITEM', '10.财产保险费：是指施工管理用财产、车辆等的保险费用。', 55, now());
INSERT INTO fee_standard_items (id, library_id, section_id, item_no, name, kind, content, sort_order, created_at) VALUES (gen_random_uuid(), 'f13aed01-cb3e-506a-bdd7-ee7fc5e5db7a', '5a227f7a-ea11-5d3e-8d1d-74d95ad22ec6', NULL, '11.财务费：是指企业为施工生产筹集资金或提供预付款担保、履约担保、职工工资支付', 'ITEM', '11.财务费：是指企业为施工生产筹集资金或提供预付款担保、履约担保、职工工资支付担保等所发生的各种费用。', 56, now());
INSERT INTO fee_standard_items (id, library_id, section_id, item_no, name, kind, content, sort_order, created_at) VALUES (gen_random_uuid(), 'f13aed01-cb3e-506a-bdd7-ee7fc5e5db7a', '5a227f7a-ea11-5d3e-8d1d-74d95ad22ec6', NULL, '12.税金：是指企业按规定缴纳的房产税、车船使用税、土地使用税、印花税等。', 'ITEM', '12.税金：是指企业按规定缴纳的房产税、车船使用税、土地使用税、印花税等。', 57, now());
INSERT INTO fee_standard_items (id, library_id, section_id, item_no, name, kind, content, sort_order, created_at) VALUES (gen_random_uuid(), 'f13aed01-cb3e-506a-bdd7-ee7fc5e5db7a', '5a227f7a-ea11-5d3e-8d1d-74d95ad22ec6', NULL, '13.工程项目附加税费：是指国家税法规定的应计入建筑安装工程造价内的城市维护建设', 'ITEM', '13.工程项目附加税费：是指国家税法规定的应计入建筑安装工程造价内的城市维护建设税、教育费附加、地方教育附加。', 58, now());
INSERT INTO fee_standard_items (id, library_id, section_id, item_no, name, kind, content, sort_order, created_at) VALUES (gen_random_uuid(), 'f13aed01-cb3e-506a-bdd7-ee7fc5e5db7a', '5a227f7a-ea11-5d3e-8d1d-74d95ad22ec6', NULL, '14.工程定位复测费：是指工程施工过程中进行全部施工测量放线和复测工作的费用。', 'ITEM', '14.工程定位复测费：是指工程施工过程中进行全部施工测量放线和复测工作的费用。', 59, now());
INSERT INTO fee_standard_items (id, library_id, section_id, item_no, name, kind, content, sort_order, created_at) VALUES (gen_random_uuid(), 'f13aed01-cb3e-506a-bdd7-ee7fc5e5db7a', '5a227f7a-ea11-5d3e-8d1d-74d95ad22ec6', NULL, '15.其他：包括技术转让费、技术开发费、投标费、业务招待费、广告费、公证费、法律', 'ITEM', '15.其他：包括技术转让费、技术开发费、投标费、业务招待费、广告费、公证费、法律顾问费、审计费、咨询费、保险费等。', 60, now());
INSERT INTO fee_standard_items (id, library_id, section_id, item_no, name, kind, content, sort_order, created_at) VALUES (gen_random_uuid(), 'f13aed01-cb3e-506a-bdd7-ee7fc5e5db7a', '5a227f7a-ea11-5d3e-8d1d-74d95ad22ec6', NULL, '（五）利润：是指施工企业完成所承包工程获得的盈利。', 'ITEM', '（五）利润：是指施工企业完成所承包工程获得的盈利。', 61, now());
INSERT INTO fee_standard_items (id, library_id, section_id, item_no, name, kind, content, sort_order, created_at) VALUES (gen_random_uuid(), 'f13aed01-cb3e-506a-bdd7-ee7fc5e5db7a', 'd8d29918-b131-5abe-97ab-605048b90c78', NULL, '各项费用费率', 'ITEM', '各项费用费率', 62, now());
INSERT INTO fee_standard_items (id, library_id, section_id, item_no, name, kind, content, sort_order, created_at) VALUES (gen_random_uuid(), 'f13aed01-cb3e-506a-bdd7-ee7fc5e5db7a', 'd8d29918-b131-5abe-97ab-605048b90c78', NULL, '一、费用计取规则：本费用标准各项费用（安全施工费、规费除外）费率均为社会平均水平', 'ITEM', '一、费用计取规则：本费用标准各项费用（安全施工费、规费除外）费率均为社会平均水平的基础费率。投标人在投标报价或承包人在非招标工程签订施工合同时，应考虑工程复杂程度、工程规模、工期要求、风险等因素确定费率。本费用标准各项费用（安全施工费除外）均以各专业工程定额分部分项工程费中的人工费与机械费之和为计费基数，其中部分专业的项目人工费与机械费之和的35%为计费基数，详见各项费用费率。', 63, now());
INSERT INTO fee_standard_items (id, library_id, section_id, item_no, name, kind, content, sort_order, created_at) VALUES (gen_random_uuid(), 'f13aed01-cb3e-506a-bdd7-ee7fc5e5db7a', '199cf009-088f-5d8d-b4fe-ff80911558e5', NULL, '1.安全施工费：以建筑安装工程不含本项费用的税前造价为取费基数。房屋建筑工程为3', 'ITEM', '1.安全施工费：以建筑安装工程不含本项费用的税前造价为取费基数。房屋建筑工程为3.27%；机电安装工程为2.18%；市政公用工程为', 64, now());
INSERT INTO fee_standard_items (id, library_id, section_id, item_no, name, kind, content, sort_order, created_at) VALUES (gen_random_uuid(), 'f13aed01-cb3e-506a-bdd7-ee7fc5e5db7a', '199cf009-088f-5d8d-b4fe-ff80911558e5', NULL, '1.71%。其中，智慧工地费用（安全施工费部分）区分工程规模，房屋建筑工程按不含', 'ITEM', '1.71%。其中，智慧工地费用（安全施工费部分）区分工程规模，房屋建筑工程按不含本项费用的税前造价为取费基数，以0.2%-0.3%计取；市政公用工程按不含本项费用的税前造价为取费基数，以0.1%-0.15%计取。', 65, now());
