INSERT INTO fee_standard_items (id, library_id, section_id, item_no, name, kind, content, sort_order, created_at) VALUES (gen_random_uuid(), 'f13aed01-cb3e-506a-bdd7-ee7fc5e5db7a', '199cf009-088f-5d8d-b4fe-ff80911558e5', NULL, '其中，智慧工地费用（文明施工和环境保护费部分）区分工程规模，房屋建筑工程按人工费', 'ITEM', '其中，智慧工地费用（文明施工和环境保护费部分）区分工程规模，房屋建筑工程按人工费与机械费之和（部分专业人工费与机械费之和的35%）为计费基数，以0.14%-0.17%计取；市政公用工程按人工费与机械费之和（部分专业人工费与机械费之和的35%）为计费基数，以0.11%-0.15%计取。', 67, now());
