INSERT INTO fee_standard_items (id, library_id, section_id, item_no, name, kind, content, sort_order, created_at) VALUES (gen_random_uuid(), 'f13aed01-cb3e-506a-bdd7-ee7fc5e5db7a', '0f4638b8-92e1-58de-8d75-e33055ebbcc7', NULL, '本费用标准中的规费，为最低费率，投标人在投标报价时，可根据企业自身情况进行上浮，', 'ITEM', '本费用标准中的规费，为最低费率，投标人在投标报价时，可根据企业自身情况进行上浮，但不得高于当地人社部门和其他有权部门的规定。最低费率为1.65%，其中仅包含社会保险费，其他项目按各市规定执行。', 76, now());
INSERT INTO fee_standard_items (id, library_id, section_id, item_no, name, kind, content, sort_order, created_at) VALUES (gen_random_uuid(), 'f13aed01-cb3e-506a-bdd7-ee7fc5e5db7a', '578e9c03-79ac-5ccd-a7fb-026003d54e08', NULL, '按《中华人民共和国税法》、财政部和国家税务总局《关于全面推开营业税改征增值税试点', 'ITEM', '按《中华人民共和国税法》、财政部和国家税务总局《关于全面推开营业税改征增值税试点的通知》（财税〔2016〕36 号）、财政部税务总局海关总署公告2019 年第39 号等相关规定执行。', 77, now());
INSERT INTO fee_standard_items (id, library_id, section_id, item_no, name, kind, content, sort_order, created_at) VALUES (gen_random_uuid(), 'f13aed01-cb3e-506a-bdd7-ee7fc5e5db7a', 'c617d30c-09f1-5111-b0d1-ab203028c44c', NULL, '招标控制价编制', 'ITEM', '招标控制价编制', 78, now());
INSERT INTO fee_standard_items (id, library_id, section_id, item_no, name, kind, content, sort_order, created_at) VALUES (gen_random_uuid(), 'f13aed01-cb3e-506a-bdd7-ee7fc5e5db7a', 'c617d30c-09f1-5111-b0d1-ab203028c44c', NULL, '一、费用计取规则：本招标控制价编制费率标准为建议费率，招标控制价编制人应根据实际', 'ITEM', '一、费用计取规则：本招标控制价编制费率标准为建议费率，招标控制价编制人应根据实际工程复杂程度、工程规模、工期要求、风险等因素自行确定费率，但不得低于本费用标准的基础费率及最低费率。各专业工程以工程定额分部分项工程费中的人工费与机械费之和为计费基数，其中部分专业的项目人工费与机械费之和的35%为计费基数，详见各项费用费率。', 79, now());
