INSERT INTO fee_standard_items (id, library_id, section_id, item_no, name, kind, content, sort_order, created_at) VALUES (gen_random_uuid(), 'f13aed01-cb3e-506a-bdd7-ee7fc5e5db7a', 'ebd89884-bc34-54ef-ac06-b5e30f817a00', NULL, '1.71%。其中，智慧工地费用（安全施工费部分）区分工程规模，房屋建筑工程按不含', 'ITEM', '1.71%。其中，智慧工地费用（安全施工费部分）区分工程规模，房屋建筑工程按不含本项费用的税前造价为取费基数，以0.2%-0.3%计取；市政公用工程按不含本项费用的税前造价为取费基数，以0.1%-0.15%计取。', 81, now());
