INSERT INTO fee_standard_items (id, library_id, section_id, item_no, name, kind, content, sort_order, created_at) VALUES (gen_random_uuid(), 'f13aed01-cb3e-506a-bdd7-ee7fc5e5db7a', 'a8d29825-fa2d-5c47-924a-280d08b12430', NULL, '本费用标准中的规费招标控制价费率应依据工程所在地人社部门的规定，结合工程实际，自', 'ITEM', '本费用标准中的规费招标控制价费率应依据工程所在地人社部门的规定，结合工程实际，自行设定。投标人在投标报价时，可根据企业自身情况进行上浮，但不得高于当地人社部门和其他有权部门的规定。最低费率为1.65%，其中仅包含社会保险费，其他项目按各市规定执行。', 92, now());
