INSERT INTO fee_standard_notes (id, library_id, section_id, note_no, content, sort_order, created_at) VALUES (gen_random_uuid(), 'f13aed01-cb3e-506a-bdd7-ee7fc5e5db7a', 'f2bd9dc6-c060-5b75-858d-32b88e58ba99', '注', '注：本表适用于建设项目招标控制价或投标报价的汇总。单项工程招标控制价/投标报价汇总表工程名称：第页共页', 1, now());
INSERT INTO fee_standard_notes (id, library_id, section_id, note_no, content, sort_order, created_at) VALUES (gen_random_uuid(), 'f13aed01-cb3e-506a-bdd7-ee7fc5e5db7a', 'f2bd9dc6-c060-5b75-858d-32b88e58ba99', '注', '注：本表适用于单项工程招标控制价或投标报价的汇总。暂估价包括分部分项工程中的暂估价和专业工程暂估价。单位工程招标控制价/投标报价汇总表工程名称：标段：第页共页', 2, now());
INSERT INTO fee_standard_notes (id, library_id, section_id, note_no, content, sort_order, created_at) VALUES (gen_random_uuid(), 'f13aed01-cb3e-506a-bdd7-ee7fc5e5db7a', 'f2bd9dc6-c060-5b75-858d-32b88e58ba99', '注', '注：本表适用于单位工程招标控制价或投标报价的汇总，如无单位工程划分，单项工程也使用本表汇总。建设项目竣工结算汇总表工程名称：第页共页', 3, now());
INSERT INTO fee_standard_notes (id, library_id, section_id, note_no, content, sort_order, created_at) VALUES (gen_random_uuid(), 'f13aed01-cb3e-506a-bdd7-ee7fc5e5db7a', 'f2bd9dc6-c060-5b75-858d-32b88e58ba99', '注', '注：如无单位工程划分，单项工程也使用本表汇总。', 4, now());
INSERT INTO fee_standard_notes (id, library_id, section_id, note_no, content, sort_order, created_at) VALUES (gen_random_uuid(), 'f13aed01-cb3e-506a-bdd7-ee7fc5e5db7a', '0c6c5e22-9bf8-5e2e-8dd6-e04d7c75e7af', '注', '注：招标文件提供了暂估单价的材料，按暂估的单价填入表内“暂估单价”栏及“暂估合价”栏。综合单价调整表工程名称：标段：第页共页', 5, now());
INSERT INTO fee_standard_notes (id, library_id, section_id, note_no, content, sort_order, created_at) VALUES (gen_random_uuid(), 'f13aed01-cb3e-506a-bdd7-ee7fc5e5db7a', '0c6c5e22-9bf8-5e2e-8dd6-e04d7c75e7af', '注', '注：综合单价调整应附调整依据。总价措施项目清单与计价表工程名称：标段：第页共页', 6, now());
INSERT INTO fee_standard_notes (id, library_id, section_id, note_no, content, sort_order, created_at) VALUES (gen_random_uuid(), 'f13aed01-cb3e-506a-bdd7-ee7fc5e5db7a', '0c6c5e22-9bf8-5e2e-8dd6-e04d7c75e7af', '注', '注：材料（工程设备）暂估单价进入清单项目综合单价，此处不汇总。暂列金额明细表工程名称：标段：第页共页', 7, now());
INSERT INTO fee_standard_notes (id, library_id, section_id, note_no, content, sort_order, created_at) VALUES (gen_random_uuid(), 'f13aed01-cb3e-506a-bdd7-ee7fc5e5db7a', '0c6c5e22-9bf8-5e2e-8dd6-e04d7c75e7af', '注', '注：此表由招标人填写，如不能详列，也可只列暂定金额总额，投标人应将上述暂列金额计入投标总价中。材料（工程设备）暂估单价及调整表工程名称：标段：第页共页', 8, now());
INSERT INTO fee_standard_notes (id, library_id, section_id, note_no, content, sort_order, created_at) VALUES (gen_random_uuid(), 'f13aed01-cb3e-506a-bdd7-ee7fc5e5db7a', '0c6c5e22-9bf8-5e2e-8dd6-e04d7c75e7af', '注', '注：此表由招标人填写“暂估单价”，并在备注栏说明暂估价的材料、工程设备拟用在哪些清单项目上，投标人应将上述材料、工程设备暂估单价计入工程量清单综合单价报价中。专业工程暂估价及结算价表工程名称：标段：第页共页', 9, now());
INSERT INTO fee_standard_notes (id, library_id, section_id, note_no, content, sort_order, created_at) VALUES (gen_random_uuid(), 'f13aed01-cb3e-506a-bdd7-ee7fc5e5db7a', '0c6c5e22-9bf8-5e2e-8dd6-e04d7c75e7af', '注', '注：此表“暂估金额”由招标人填写，投标人应将“暂估金额”计入投标总价中。结算时按合同约定结算金额填写。计日工表工程名称：标段：第页共页', 10, now());
INSERT INTO fee_standard_notes (id, library_id, section_id, note_no, content, sort_order, created_at) VALUES (gen_random_uuid(), 'f13aed01-cb3e-506a-bdd7-ee7fc5e5db7a', '0c6c5e22-9bf8-5e2e-8dd6-e04d7c75e7af', '注', '注：此表项目名称、暂定数量由招标人填写，编制招标控制价时，单价由招标人按有关计价规定确定；投标时，单价由投标人自主报价，按暂定数量计算合价计入投标总价中。结算时，按发承包双方确认的实际数量计算合价。总承包服务费计价表工程名称：标段：第页共页', 11, now());
INSERT INTO fee_standard_notes (id, library_id, section_id, note_no, content, sort_order, created_at) VALUES (gen_random_uuid(), 'f13aed01-cb3e-506a-bdd7-ee7fc5e5db7a', '0c6c5e22-9bf8-5e2e-8dd6-e04d7c75e7af', '注', '注：此表项目名称、服务内容由招标人填写，编制招标控制价时，费率及金额由招标人按有关计价规定确定；投标时，费率及金额由投标人自主报价，计入投标总价中。规费、税金项目计价表工程名称：标段：第页共页', 12, now());
INSERT INTO fee_standard_notes (id, library_id, section_id, note_no, content, sort_order, created_at) VALUES (gen_random_uuid(), 'f13aed01-cb3e-506a-bdd7-ee7fc5e5db7a', '0c6c5e22-9bf8-5e2e-8dd6-e04d7c75e7af', '注', '注：此表由招标人填写，供投标人在投标报价、确定总承包服务费时参考。承包人提供主要材料和工程设备一览表（适用于造价信息差额调整法）工程名称：标段：第页共页', 13, now());
INSERT INTO fee_standard_notes (id, library_id, section_id, note_no, content, sort_order, created_at) VALUES (gen_random_uuid(), 'f13aed01-cb3e-506a-bdd7-ee7fc5e5db7a', '0c6c5e22-9bf8-5e2e-8dd6-e04d7c75e7af', '注', '注：1 此表由招标人填写除“投标单价”栏的内容，投标人在投标报价时自主确定投标单价。2 招标人应优先采用工程造价管理机构发布的单价作为基准单价，未发布的，通过市场调查确定其基准单价。承包人提供主要材料和工程设备一览表（适用于价格指数差额调整法）工程名称：标段：第页共页', 14, now());
INSERT INTO fee_standard_notes (id, library_id, section_id, note_no, content, sort_order, created_at) VALUES (gen_random_uuid(), 'f13aed01-cb3e-506a-bdd7-ee7fc5e5db7a', '0c6c5e22-9bf8-5e2e-8dd6-e04d7c75e7af', '注', '注：1“名称、规格、型号”、“基本价格指数”栏由招标人填写，基本价格指数应首先采用工程造价管理机构发布的价格指数，没有时，可采用发布的价格代替。如人工、机械费也采用本法调整，由招标人在“名称”栏填写。2“变值权重”栏由投标人根据该项人工、机械费和材料、工程设备价值在投标总报价中所占比例填写，1 减去其比例为定值权重。3“现行价格指数”按约定的付款证书相关周期最后一天的前42 天的各项价格指数填写，该指数应首先采用工程造价管理机构发布的价格指数，没有时，可采用发布的价格代替。其他表格可参照《建设工程工程量清单计价规范》（GB50500-2013）', 15, now());
